// Pseudo-code: validate that RLS is enabled for a tenant database (illustrative)
function validateTenantDB(config){
  if(!config.sql || !config.sql.rlsEnabled){
    throw new Error("RLS must be enabled per tenant database");
  }
  return true;
}
```

